<?php
namespace App\Http\Controllers\Api;
use App\Models\Coupon; use Illuminate\Http\Request;
class CouponController extends BaseApiController { public function validateCoupon(Request $r){$code=strtoupper(trim((string)$r->input('code')));$subtotal=(float)$r->input('subtotal',0);$c=Coupon::whereRaw('UPPER(code)=?',[$code])->first();if(!$c||!$c->is_active||($c->starts_at&&$c->starts_at->isFuture())||($c->expires_at&&$c->expires_at->isPast())||($c->usage_limit!==null&&$c->used_count >= $c->usage_limit))return $this->fail('কুপনটি ব্যবহার করা যাবে না',422);if($subtotal<(float)$c->min_order)return $this->fail('Minimum order required',422);$discount=$c->discount_type==='percent'?round($subtotal*(float)$c->discount_value/100,2):min((float)$c->discount_value,$subtotal);if($c->max_discount!==null)$discount=min($discount,(float)$c->max_discount);return $this->ok(['code'=>$c->code,'discount_amount'=>$discount,'discount_type'=>$c->discount_type]);} public function legacyGet(Request $r){$c=Coupon::whereRaw('UPPER(code)=?', [strtoupper((string)$r->query('code'))])->first();return $this->ok($c);} }
